-- S15: script adaptado a PostgreSQL (Supabase) para la base de datos en la nube.
-- Mismo modelo que script.sql (SQL Server): Propietarios 1 -- N Mascotas + Usuarios (JWT).
-- Se usan identificadores entre comillas para respetar los nombres PascalCase que usa EF Core.

DROP TABLE IF EXISTS "Usuarios";
DROP TABLE IF EXISTS "Mascotas";
DROP TABLE IF EXISTS "Propietarios";

CREATE TABLE "Propietarios"
(
    "Id"        INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre"    VARCHAR(60)  NOT NULL,
    "Apellido"  VARCHAR(60)  NOT NULL,
    "Email"     VARCHAR(120) NOT NULL,
    "Telefono"  VARCHAR(20)  NULL,
    "Direccion" VARCHAR(150) NULL,
    CONSTRAINT "UQ_Propietarios_Email" UNIQUE ("Email")
);

CREATE TABLE "Mascotas"
(
    "Id"              INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre"          VARCHAR(60)   NOT NULL,
    "Especie"         VARCHAR(40)   NOT NULL,
    "Raza"            VARCHAR(40)   NULL,
    "FechaNacimiento" TIMESTAMP     NOT NULL,
    "Peso"            DECIMAL(6,2)  NOT NULL,
    "PropietarioId"   INT           NOT NULL,
    CONSTRAINT "FK_Mascotas_Propietarios"
        FOREIGN KEY ("PropietarioId") REFERENCES "Propietarios"("Id")
);

CREATE TABLE "Usuarios"
(
    "Id"        INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Correo"    VARCHAR(120) NOT NULL,
    "ClaveHash" VARCHAR(100) NOT NULL,
    "Rol"       VARCHAR(30)  NOT NULL,
    CONSTRAINT "UQ_Usuarios_Correo" UNIQUE ("Correo"),
    CONSTRAINT "CK_Usuarios_Rol" CHECK ("Rol" IN ('Veterinario', 'Recepcionista'))
);

